export const SPICE_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/spice-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getSpiceStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(SPICE_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
